CREATE DATABASE IF NOT EXISTS BIM216_Project; USE BIM216_Project;
CREATE TABLE ADVISOR ( AdvisorID int not null primary key, AD_FullName varchar(100) not null, AD_Email varchar(100) not null, AD_Password varchar(100) not null, constraint AD_Email unique (AD_Email) );
CREATE TABLE STUDENT ( StudentID int not null primary key, AdvisorID int null, ST_FullName varchar(100) not null, ST_Email varchar(100) not null, RegistrationDate date null, ST_Password varchar(100) not null, constraint ST_Email unique (ST_Email), constraint student_ibfk_1 foreign key (AdvisorID) references BIM216_Project.ADVISOR (AdvisorID) on delete set null );
create index AdvisorID on STUDENT (AdvisorID);
CREATE TABLE SUBJECT ( SubjectID int not null primary key, AdvisorID int null, SubjectName varchar(100) not null, Category varchar(50) null, DifficultyLevel int null, constraint subject_ibfk_1 foreign key (AdvisorID) references BIM216_Project.ADVISOR (AdvisorID) on delete set null );
create index AdvisorID on SUBJECT (AdvisorID);
CREATE TABLE GOALS ( GoalID int auto_increment primary key, StudentID int null, SubjectID int null, WeekStartDate date null, TargetStudyHours decimal(5, 2) null, TargetQuizScore decimal(5, 2) null, EndDate date null, IsCompleted tinyint(1) default 0 null, constraint goals_ibfk_1 foreign key (StudentID) references BIM216_Project.STUDENT (StudentID) on delete cascade, constraint goals_ibfk_2 foreign key (SubjectID) references BIM216_Project.SUBJECT (SubjectID) on delete cascade );
create index StudentID on GOALS (StudentID);
create index SubjectID on GOALS (SubjectID);
CREATE TABLE INSIGHT_RECORDS ( RecommendationID int not null primary key, StudentID int null, RecommendationText text null, RecommendationType varchar(50) null, PatternDetected varchar(100) null, GeneratedDate datetime null, constraint insight_records_ibfk_1 foreign key (StudentID) references BIM216_Project.STUDENT (StudentID) on delete cascade );
create index StudentID on INSIGHT_RECORDS (StudentID);
CREATE TABLE QUIZ_RECORDS ( QuizID int auto_increment primary key, StudentID int null, SubjectID int null, Score decimal(5, 2) null, MaxScore decimal(5, 2) null, MinScore decimal(5, 2) null, QuizDate date null, constraint quiz_records_ibfk_1 foreign key (StudentID) references BIM216_Project.STUDENT (StudentID) on delete cascade, constraint quiz_records_ibfk_2 foreign key (SubjectID) references BIM216_Project.SUBJECT (SubjectID) on delete cascade );
create index StudentID on QUIZ_RECORDS (StudentID);
create index SubjectID on QUIZ_RECORDS (SubjectID);
CREATE TABLE STUDY_SESSIONS ( SessionID int auto_increment primary key, StudentID int null, SubjectID int null, StartTime time null, EndTime time null, SessionDate date null, FocusLevel int null, SessionNote text null, constraint study_sessions_ibfk_1 foreign key (StudentID) references BIM216_Project.STUDENT (StudentID) on delete cascade, constraint study_sessions_ibfk_2 foreign key (SubjectID) references BIM216_Project.SUBJECT (SubjectID) on delete cascade );
create index StudentID on STUDY_SESSIONS (StudentID);
create index SubjectID on STUDY_SESSIONS (SubjectID);
